  const toolRegistry = new ToolRegistry();
  toolRegistry.register({name: 'echo', description: 'echo', inputSchema: {type: 'object'}}, async () => ({
    result: 'echoed',
  }));

  const toolRound = (id: string, usage?: UsageMetadata): MessageChunk[] => [
    {type: 'tool_use', toolCall: {id, name: 'echo', input: {}}},
    {type: 'stop', stopReason: 'tool_use', usage},
  ];

  const finalRound = (usage?: UsageMetadata): MessageChunk[] => [
    {type: 'text', text: 'done'},
    {type: 'stop', stopReason: 'end_turn', usage},
  ];

  async function runTurn(rounds: MessageChunk[][]): Promise<UsageMetadata | undefined> {
    let reportedUsage: UsageMetadata | undefined;
    const provider = scriptedProvider(rounds);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, toolRegistry, {
      hooks: {
        afterModelResponse: async (_session, _text, usage) => {
          reportedUsage = usage;
        },
      },
    });

    await orchestrator.processMessage(session);
    return reportedUsage;
  }

  it('accumulates usage across multiple tool rounds', async () => {
    const reportedUsage = await runTurn([
      toolRound('c1', {inputTokens: 100, outputTokens: 10, totalTokens: 110}),
      finalRound({inputTokens: 200, outputTokens: 20, totalTokens: 220}),
    ]);

    expect(reportedUsage).toEqual({
      inputTokens: 300,
      outputTokens: 30,
      totalTokens: 330,
    });
  });

  it('reports undefined when no rounds reported usage', async () => {
    const reportedUsage = await runTurn([toolRound('c1'), finalRound()]);

    expect(reportedUsage).toBeUndefined();
  });

  it('accumulates usage across three rounds where one is missing usage', async () => {
    const reportedUsage = await runTurn([
      toolRound('c1', {inputTokens: 100, outputTokens: 10, totalTokens: 110}),
      toolRound('c2'),
      finalRound({inputTokens: 200, outputTokens: 20, totalTokens: 220}),
    ]);

    expect(reportedUsage).toEqual({
      inputTokens: 300,
      outputTokens: 30,
      totalTokens: 330,
    });
  });
});

